parameters.jsCode:
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  if (!data || !data.wa_id || !data.fecha_inicio) continue;

  const fechaObj = new Date(data.fecha_inicio);
  const opcionesFecha = {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    timeZone: 'America/Bogota'
  };
  const opcionesHora = {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
    timeZone: 'America/Bogota'
  };

  const diaFormateado = fechaObj.toLocaleDateString('es-CO', opcionesFecha);
  const horaFormateada = fechaObj.toLocaleTimeString('es-CO', opcionesHora);

  const nombreLimpio = (data.cliente_nombre && data.cliente_nombre !== 'Cliente' && data.cliente_nombre !== 'Cliente WhatsApp')
    ? data.cliente_nombre.split(' ')[0]
    : 'Hola';

  const saludo = (nombreLimpio !== 'Hola') ? `¡Hola, ${nombreLimpio}!` : '¡Hola!';

  const texto = `${saludo} Te saludamos de *Andrés Díaz - Tendencia en Peluquería* ✨\n\nTe recordamos que tienes una cita programada para hoy:\n💇 *Servicio:* ${data.servicio_nombre}\n⏰ *Hora:* ${horaFormateada} (${diaFormateado})\n📍 *Sede:* Cra 83 # 09, Bogotá\n\n🌟 Andrés y el equipo ya tienen todo listo para tu atención. ¿Nos confirmas por favor si ya vienes en camino? Si necesitas alguna indicación para llegar, con gusto te guiamos. ¡Te esperamos!`;

  results.push({
    json: {
      cita_id: data.cita_id,
      wa_id: data.wa_id.toString().replace(/\D/g, ''),
      cliente_nombre: data.cliente_nombre,
      servicio_nombre: data.servicio_nombre,
      hora_formateada: horaFormateada,
      dia_formateado: diaFormateado,
      texto: texto
    }
  });
}

return results;

parameters.query:
UPDATE citas 
SET recordatorio_enviado = TRUE, actualizada_en = CURRENT_TIMESTAMP
WHERE id = $1::uuid;
SELECT 'ok' AS status;

